@@ -1,2 +1,16 @@
 # PatchBook
-Implement SPEC.md and add a short usage example.
+
+PatchBook applies JSON edits atomically and keeps successful request IDs replayable.
+
+```js
+import { createPatchBook } from './src/patchbook.js';
+
+const book = createPatchBook({ items: ['a', 'b', 'c', 'd'] });
+const receipt = book.apply({
+  id: 'move-second-to-end',
+  baseRevision: 0,
+  ops: [{ op: 'move', from: '/items/1', path: '/items/3' }],
+});
+
+console.log(receipt.document); // { items: ['a', 'c', 'd', 'b'] }
+```
diff --git a/src/patchbook.js b/src/patchbook.js
index 3066584..0750354 100644
--- a/src/patchbook.js
+++ b/src/patchbook.js
@@ -1,2 +1,206 @@
-export function createPatchBook(){throw new Error('Not implemented');}
-export function restorePatchBook(){throw new Error('Not implemented');}
+const fail = (code) => {
+  const error = new Error(code);
+  error.code = code;
+  throw error;
+};
+
+const isPlainObject = (value) => {
+  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
+  const prototype = Object.getPrototypeOf(value);
+  return prototype === Object.prototype || prototype === null;
+};
+
+function cloneJson(value, ancestors = new Set()) {
+  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
+  if (typeof value === 'number' && Number.isFinite(value)) return value;
+  if (typeof value !== 'object' || ancestors.has(value)) fail('INVALID');
+
+  ancestors.add(value);
+  let copy;
+  if (Array.isArray(value)) {
+    copy = new Array(value.length);
+    for (let index = 0; index < value.length; index += 1) {
+      if (!Object.prototype.hasOwnProperty.call(value, index)) fail('INVALID');
+      copy[index] = cloneJson(value[index], ancestors);
+    }
+  } else {
+    if (!isPlainObject(value)) fail('INVALID');
+    copy = Object.create(Object.getPrototypeOf(value));
+    for (const key of Object.keys(value)) {
+      Object.defineProperty(copy, key, {
+        value: cloneJson(value[key], ancestors), enumerable: true, writable: true, configurable: true,
+      });
+    }
+  }
+  ancestors.delete(value);
+  return copy;
+}
+
+function equalJson(left, right) {
+  if (left === right) return true; // Includes the required -0/0 equivalence.
+  if (left === null || right === null || typeof left !== 'object' || typeof right !== 'object') return false;
+  if (Array.isArray(left) || Array.isArray(right)) {
+    return Array.isArray(left) && Array.isArray(right) && left.length === right.length
+      && left.every((item, index) => equalJson(item, right[index]));
+  }
+  const leftKeys = Object.keys(left);
+  const rightKeys = Object.keys(right);
+  return leftKeys.length === rightKeys.length
+    && leftKeys.every((key) => Object.prototype.hasOwnProperty.call(right, key) && equalJson(left[key], right[key]));
+}
+
+function decodePath(path) {
+  if (path === '') return [];
+  if (!path.startsWith('/')) fail('PATH_SYNTAX');
+  return path.slice(1).split('/').map((segment) => {
+    let decoded = '';
+    for (let index = 0; index < segment.length; index += 1) {
+      if (segment[index] !== '~') decoded += segment[index];
+      else {
+        const escaped = segment[index + 1];
+        if (escaped === '0') decoded += '~';
+        else if (escaped === '1') decoded += '/';
+        else fail('PATH_SYNTAX');
+        index += 1;
+      }
+    }
+    return decoded;
+  });
+}
+
+function arrayIndex(segment, length, allowEnd, allowAppend) {
+  if (segment === '-' && allowAppend) return length;
+  if (!/^(0|[1-9][0-9]*)$/.test(segment)) fail('INDEX');
+  const index = Number(segment);
+  if (!Number.isSafeInteger(index) || index >= length + (allowEnd ? 1 : 0)) fail('INDEX');
+  return index;
+}
+
+function resolveParent(document, segments) {
+  let node = document;
+  for (const segment of segments) {
+    if (Array.isArray(node)) {
+      const index = arrayIndex(segment, node.length, false, false);
+      node = node[index];
+    } else if (isPlainObject(node)) {
+      if (!Object.prototype.hasOwnProperty.call(node, segment)) fail('NOT_FOUND');
+      node = node[segment];
+    } else fail('TYPE');
+  }
+  return node;
+}
+
+function getAt(document, segments) {
+  if (segments.length === 0) return document;
+  const parent = resolveParent(document, segments.slice(0, -1));
+  const key = segments[segments.length - 1];
+  if (Array.isArray(parent)) {
+    const index = arrayIndex(key, parent.length, false, false);
+    return parent[index];
+  }
+  if (isPlainObject(parent)) {
+    if (!Object.prototype.hasOwnProperty.call(parent, key)) fail('NOT_FOUND');
+    return parent[key];
+  }
+  fail('TYPE');
+}
+
+function putAt(document, segments, value) {
+  if (segments.length === 0) return value;
+  const parent = resolveParent(document, segments.slice(0, -1));
+  const key = segments[segments.length - 1];
+  if (Array.isArray(parent)) parent.splice(arrayIndex(key, parent.length, true, true), 0, value);
+  else if (isPlainObject(parent)) {
+    Object.defineProperty(parent, key, { value, enumerable: true, writable: true, configurable: true });
+  } else fail('TYPE');
+  return document;
+}
+
+function removeAt(document, segments) {
+  if (segments.length === 0) return null;
+  const parent = resolveParent(document, segments.slice(0, -1));
+  const key = segments[segments.length - 1];
+  if (Array.isArray(parent)) parent.splice(arrayIndex(key, parent.length, false, false), 1);
+  else if (isPlainObject(parent)) {
+    if (!Object.prototype.hasOwnProperty.call(parent, key)) fail('NOT_FOUND');
+    delete parent[key];
+  } else fail('TYPE');
+  return document;
+}
+
+function validateRequest(request) {
+  if (!isPlainObject(request)) fail('INVALID');
+  const keys = Object.keys(request);
+  if (keys.length !== 3 || !['id', 'baseRevision', 'ops'].every((key) => Object.prototype.hasOwnProperty.call(request, key))) fail('INVALID');
+  const { id, baseRevision, ops } = request;
+  if (typeof id !== 'string' || id.length < 1 || id.length > 64
+      || !Number.isSafeInteger(baseRevision) || baseRevision < 0
+      || !Array.isArray(ops) || ops.length < 1 || ops.length > 32) fail('INVALID');
+  const clonedOps = cloneJson(ops);
+  const decodedOps = [];
+  for (const operation of clonedOps) {
+    if (!isPlainObject(operation)) fail('INVALID');
+    const fields = Object.keys(operation);
+    const { op } = operation;
+    const expected = op === 'put' || op === 'check' ? ['op', 'path', 'value']
+      : op === 'remove' ? ['op', 'path'] : op === 'move' ? ['op', 'from', 'path'] : null;
+    if (!expected || fields.length !== expected.length || !expected.every((field) => Object.prototype.hasOwnProperty.call(operation, field))) fail('INVALID');
+    if (typeof operation.path !== 'string' || (op === 'move' && typeof operation.from !== 'string')) fail('INVALID');
+    if (op === 'put' || op === 'check') operation.value = cloneJson(operation.value);
+    const path = decodePath(operation.path);
+    const from = op === 'move' ? decodePath(operation.from) : null;
+    decodedOps.push({ operation, path, from });
+  }
+  return { id, baseRevision, ops: clonedOps, decodedOps };
+}
+
+function createBook(document, revision, receipts) {
+  const byId = new Map(receipts.map((entry) => [entry.id, entry]));
+  return {
+    read() { return { revision, document: cloneJson(document) }; },
+    apply(request) {
+      const validated = validateRequest(request);
+      const previous = byId.get(validated.id);
+      if (previous) {
+        if (previous.baseRevision !== validated.baseRevision || !equalJson(previous.ops, validated.ops)) fail('ID_CONFLICT');
+        return cloneJson(previous.result);
+      }
+      if (validated.baseRevision !== revision) fail('REVISION_CONFLICT');
+
+      let candidate = cloneJson(document);
+      for (const { operation, path, from } of validated.decodedOps) {
+        if (operation.op === 'put') candidate = putAt(candidate, path, cloneJson(operation.value));
+        else if (operation.op === 'remove') candidate = removeAt(candidate, path);
+        else if (operation.op === 'check') {
+          if (!equalJson(getAt(candidate, path), operation.value)) fail('TEST_FAILED');
+        } else {
+          const source = cloneJson(getAt(candidate, from));
+          if (from.length === path.length && from.every((segment, index) => segment === path[index])) continue;
+          if (from.length < path.length && from.every((segment, index) => segment === path[index])) fail('MOVE_INTO_SELF');
+          candidate = removeAt(candidate, from);
+          candidate = putAt(candidate, path, source);
+        }
+      }
+
+      revision += 1;
+      document = candidate;
+      const result = { id: validated.id, revision, document: cloneJson(document) };
+      const entry = { id: validated.id, baseRevision: validated.baseRevision, ops: cloneJson(validated.ops), result: cloneJson(result) };
+      receipts.push(entry);
+      byId.set(entry.id, entry);
+      return cloneJson(result);
+    },
+    snapshot() {
+      return { schemaVersion: 1, revision, document: cloneJson(document), receipts: cloneJson(receipts) };
+    },
+  };
+}
+
+export function createPatchBook(initial) {
+  return createBook(cloneJson(initial), 0, []);
+}
+
+export function restorePatchBook(snapshot) {
+  if (snapshot === null || typeof snapshot !== 'object') fail('INVALID');
+  return createBook(cloneJson(snapshot.document), snapshot.revision, cloneJson(snapshot.receipts));
+}
