@@ -0,0 +1,249 @@
+import { test, expect } from 'vitest';
+import * as api from '../src/patchbook.js';
+
+const codeOf = async (call) => {
+  try { await call(); } catch (error) { return error?.code; }
+  return 'NO_ERROR';
+};
+const keys = (value) => Object.keys(value).sort();
+
+// @aidept-case C-1
+test('[R-1][R-2][C-1] exports and detached root null read', async () => {
+  // @aidept-step S-1
+  expect(Object.keys(api).sort()).toEqual(['createPatchBook', 'restorePatchBook']);
+  const book = await api.createPatchBook(null);
+  const first = await book.read();
+  // @aidept-step S-2
+  expect(first).toEqual({ revision: 0, document: null });
+  // @aidept-step S-2
+  expect(keys(first)).toEqual(['document', 'revision']);
+  first.document = { changed: true };
+  const second = await book.read();
+  // @aidept-step S-3
+  expect(second).toEqual({ revision: 0, document: null });
+});
+
+// @aidept-case C-2
+test('[R-3][C-2] rejects invalid JSON document values', async () => {
+  const sparse = []; sparse.length = 1;
+  const cyclic = {}; cyclic.self = cyclic;
+  const values = [undefined, NaN, Infinity, sparse, cyclic, new Date()];
+  for (const value of values) {
+    // @aidept-step S-1
+    expect(await codeOf(() => api.createPatchBook(value))).toBe('INVALID');
+  }
+});
+
+// @aidept-case C-3
+test('[R-4][C-3] rejects invalid apply request and operation shapes', async () => {
+  const book = await api.createPatchBook({});
+  const valid = { id: 'i', baseRevision: 0, ops: [{ op: 'put', path: '/x', value: 1 }] };
+  const badRequests = [null, Object.assign(Object.create({ inherited: true }), valid), { id: 'i', baseRevision: 0 }, { ...valid, extra: 1 }, { ...valid, id: '' }, { ...valid, id: 'x'.repeat(65) }, { ...valid, baseRevision: -1 }, { ...valid, baseRevision: 1.5 }, { ...valid, baseRevision: Number.MAX_SAFE_INTEGER + 1 }, { ...valid, ops: [] }, { ...valid, ops: Array.from({ length: 33 }, () => ({ op: 'remove', path: '' })) }, { ...valid, ops: new Array(1) }];
+  for (const request of badRequests) {
+    // @aidept-step S-1
+    expect(await codeOf(() => book.apply(request))).toBe('INVALID');
+  }
+  const badOps = [null, { op: 'remove' }, { op: 'remove', path: '', extra: 1 }, { op: 'wat', path: '' }, { op: 'put', path: 2, value: 1 }, { op: 'put', path: '', value: undefined }, { op: 'move', from: 1, path: '' }];
+  for (const op of badOps) {
+    // @aidept-step S-2
+    expect(await codeOf(() => book.apply({ id: 'bad', baseRevision: 0, ops: [op] }))).toBe('INVALID');
+  }
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 0, document: {} });
+});
+
+// @aidept-case C-4
+test('[R-5][C-4] validates pointer syntax and supports literal decoded keys', async () => {
+  const book = await api.createPatchBook({});
+  for (const path of ['abc', '/x~', '/x~2']) {
+    // @aidept-step S-1
+    expect(await codeOf(() => book.apply({ id: `bad-${path}`, baseRevision: 0, ops: [{ op: 'put', path, value: 1 }] }))).toBe('PATH_SYNTAX');
+  }
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 0, document: {} });
+  const ops = [
+    { op: 'put', path: '/', value: 'empty' }, { op: 'put', path: '/__proto__', value: { safe: true } },
+    { op: 'put', path: '/constructor', value: 3 }, { op: 'put', path: '/prototype', value: 4 },
+    { op: 'put', path: '/a~0b', value: 5 }, { op: 'put', path: '/a~1b', value: 6 },
+  ];
+  await book.apply({ id: 'keys', baseRevision: 0, ops });
+  const result = await book.read();
+  const expected = Object.fromEntries([['', 'empty'], ['__proto__', { safe: true }], ['constructor', 3], ['prototype', 4], ['a~b', 5], ['a/b', 6]]);
+  // @aidept-step S-2
+  expect(result.document).toEqual(expected);
+  // @aidept-step S-2
+  expect(Object.getPrototypeOf(result.document)).toBe(Object.prototype);
+  // @aidept-step S-2
+  expect(Object.prototype.safe).toBeUndefined();
+});
+
+// @aidept-case C-5
+test('[R-6][R-7][C-5] path lookup errors and array append destination', async () => {
+  const book = await api.createPatchBook({ obj: {}, n: null, p: 3, arr: ['x'] });
+  const requests = [
+    [{ op: 'check', path: '/obj/missing', value: 1 }, 'NOT_FOUND'],
+    [{ op: 'check', path: '/n/x', value: 1 }, 'TYPE'],
+    [{ op: 'check', path: '/p/x', value: 1 }, 'TYPE'],
+    [{ op: 'check', path: '/arr/01', value: 1 }, 'INDEX'],
+    [{ op: 'check', path: '/arr/1', value: 1 }, 'INDEX'],
+    [{ op: 'remove', path: '/arr/-' }, 'INDEX'],
+    [{ op: 'move', from: '/arr/-', path: '/obj/x' }, 'INDEX'],
+  ];
+  for (const [op, code] of requests) {
+    // @aidept-step S-1
+    expect(await codeOf(() => book.apply({ id: `err-${code}-${op.path ?? op.from}`, baseRevision: 0, ops: [op] }))).toBe(code);
+  }
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 0, document: { obj: {}, n: null, p: 3, arr: ['x'] } });
+  await book.apply({ id: 'append', baseRevision: 0, ops: [{ op: 'put', path: '/arr/-', value: 'y' }] });
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 1, document: { obj: {}, n: null, p: 3, arr: ['x', 'y'] } });
+});
+
+// @aidept-case C-6
+test('[R-7][C-6] put and remove object, array, and root targets', async () => {
+  const book = await api.createPatchBook({ items: ['a', 'b'], obj: { x: 1 } });
+  await book.apply({ id: 'puts', baseRevision: 0, ops: [{ op: 'put', path: '/obj/y', value: 2 }, { op: 'put', path: '/items/1', value: 'z' }] });
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 1, document: { items: ['a', 'z', 'b'], obj: { x: 1, y: 2 } } });
+  await book.apply({ id: 'removes', baseRevision: 1, ops: [{ op: 'remove', path: '/items/1' }, { op: 'remove', path: '/obj/y' }] });
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 2, document: { items: ['a', 'b'], obj: { x: 1 } } });
+  await book.apply({ id: 'root', baseRevision: 2, ops: [{ op: 'remove', path: '' }] });
+  // @aidept-step S-3
+  expect(await book.read()).toEqual({ revision: 3, document: null });
+});
+
+// @aidept-case C-7
+test('[R-8][R-11][C-7] check equality and rollback on mismatches', async () => {
+  const book = await api.createPatchBook({ obj: { a: 1, b: 2 }, arr: [1, 2], zero: 0 });
+  const receipt = await book.apply({ id: 'checks', baseRevision: 0, ops: [{ op: 'check', path: '/obj', value: { b: 2, a: 1 } }, { op: 'check', path: '/zero', value: -0 }] });
+  // @aidept-step S-1
+  expect(receipt).toEqual({ id: 'checks', revision: 1, document: { obj: { a: 1, b: 2 }, arr: [1, 2], zero: 0 } });
+  // @aidept-step S-1
+  expect((await book.snapshot()).receipts).toHaveLength(1);
+  const arrayError = await codeOf(() => book.apply({ id: 'array-order', baseRevision: 1, ops: [{ op: 'check', path: '/arr', value: [2, 1] }] }));
+  // @aidept-step S-2
+  expect(arrayError).toBe('TEST_FAILED');
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 1, document: { obj: { a: 1, b: 2 }, arr: [1, 2], zero: 0 } });
+  // @aidept-step S-2
+  expect((await book.snapshot()).receipts).toHaveLength(1);
+  const objectError = await codeOf(() => book.apply({ id: 'object-value', baseRevision: 1, ops: [{ op: 'check', path: '/obj', value: { a: 9 } }] }));
+  // @aidept-step S-3
+  expect(objectError).toBe('TEST_FAILED');
+  // @aidept-step S-3
+  expect(await book.read()).toEqual({ revision: 1, document: { obj: { a: 1, b: 2 }, arr: [1, 2], zero: 0 } });
+  // @aidept-step S-3
+  expect((await book.snapshot()).receipts).toHaveLength(1);
+});
+
+// @aidept-case C-8
+test('[R-9][R-11][C-8] move descendant rejection, post-removal destinations, and no-op', async () => {
+  const book = await api.createPatchBook({ a: { b: 1 }, ab: 2, items: ['a', 'b', 'c', 'd'] });
+  const err = await codeOf(() => book.apply({ id: 'descendant', baseRevision: 0, ops: [{ op: 'move', from: '/a', path: '/a/b/c' }] }));
+  // @aidept-step S-1
+  expect(err).toBe('MOVE_INTO_SELF');
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 0, document: { a: { b: 1 }, ab: 2, items: ['a', 'b', 'c', 'd'] } });
+  await book.apply({ id: 'moves', baseRevision: 0, ops: [{ op: 'move', from: '/a', path: '/ab' }, { op: 'move', from: '/items/1', path: '/items/3' }] });
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 1, document: { ab: { b: 1 }, items: ['a', 'c', 'd', 'b'] } });
+  const noop = await book.apply({ id: 'noop', baseRevision: 1, ops: [{ op: 'move', from: '/items/1', path: '/items/1' }] });
+  // @aidept-step S-3
+  expect(noop).toEqual({ id: 'noop', revision: 2, document: { ab: { b: 1 }, items: ['a', 'c', 'd', 'b'] } });
+  const lifted = await book.apply({ id: 'lift', baseRevision: 2, ops: [{ op: 'move', from: '/ab/b', path: '' }] });
+  // @aidept-step S-3
+  expect(lifted).toEqual({ id: 'lift', revision: 3, document: 1 });
+});
+
+// @aidept-case C-9
+test('[R-10][R-11][C-9] validation order, rollback, retry, and revision conflict', async () => {
+  const book = await api.createPatchBook({ a: 1 });
+  const failed = await codeOf(() => book.apply({ id: 'retry', baseRevision: 0, ops: [{ op: 'put', path: '/b', value: 2 }, { op: 'check', path: '/a', value: 9 }] }));
+  // @aidept-step S-1
+  expect(failed).toBe('TEST_FAILED');
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 0, document: { a: 1 } });
+  // @aidept-step S-1
+  expect((await book.snapshot()).receipts).toEqual([]);
+  const receipt = await book.apply({ id: 'retry', baseRevision: 0, ops: [{ op: 'put', path: '/b', value: 2 }] });
+  // @aidept-step S-2
+  expect(receipt).toEqual({ id: 'retry', revision: 1, document: { a: 1, b: 2 } });
+  const conflict = await codeOf(() => book.apply({ id: 'stale', baseRevision: 0, ops: [{ op: 'check', path: '/missing', value: 1 }] }));
+  // @aidept-step S-3
+  expect(conflict).toBe('REVISION_CONFLICT');
+  const syntax = await codeOf(() => book.apply({ id: 'retry', baseRevision: 0, ops: [{ op: 'check', path: '/bad~', value: 1 }] }));
+  // @aidept-step S-4
+  expect(syntax).toBe('PATH_SYNTAX');
+});
+
+// @aidept-case C-10
+test('[R-10][R-12][R-13][R-11][C-10] historical replay and snapshot restore', async () => {
+  const book = await api.createPatchBook({ a: 1 });
+  const x = { id: 'X', baseRevision: 0, ops: [{ op: 'put', path: '/b', value: 2 }] };
+  await book.apply(x);
+  await book.apply({ id: 'Y', baseRevision: 1, ops: [{ op: 'remove', path: '/a' }] });
+  // @aidept-step S-1
+  expect(await book.read()).toEqual({ revision: 2, document: { b: 2 } });
+  const old = await book.apply(x);
+  // @aidept-step S-2
+  expect(old).toEqual({ id: 'X', revision: 1, document: { a: 1, b: 2 } });
+  // @aidept-step S-2
+  expect(await book.read()).toEqual({ revision: 2, document: { b: 2 } });
+  const diffBase = await codeOf(() => book.apply({ ...x, baseRevision: 2 }));
+  const diffOps = await codeOf(() => book.apply({ ...x, ops: [{ op: 'put', path: '/b', value: 3 }] }));
+  // @aidept-step S-3
+  expect([diffBase, diffOps]).toEqual(['ID_CONFLICT', 'ID_CONFLICT']);
+  const snapshot = await book.snapshot();
+  // @aidept-step S-4
+  expect(keys(snapshot)).toEqual(['document', 'receipts', 'revision', 'schemaVersion']);
+  // @aidept-step S-4
+  expect(snapshot.receipts).toEqual([
+    { id: 'X', baseRevision: 0, ops: x.ops, result: { id: 'X', revision: 1, document: { a: 1, b: 2 } } },
+    { id: 'Y', baseRevision: 1, ops: [{ op: 'remove', path: '/a' }], result: { id: 'Y', revision: 2, document: { b: 2 } } },
+  ]);
+  const restored = await api.restorePatchBook(JSON.parse(JSON.stringify(snapshot)));
+  // @aidept-step S-4
+  expect(await restored.snapshot()).toEqual(snapshot);
+  const replay = await restored.apply(x);
